DO $m$ DECLARE r jsonb := current_setting('daa.control_result')::jsonb; f jsonb := '[["00000000-0000-4000-8000-000000000001", 1, -1], ["00000000-0000-4000-8000-000000000002", 1, -2], ["00000000-0000-4000-8000-000000000003", 1, -3], ["00000000-0000-4000-8000-000000000004", 1, -4], ["00000000-0000-4000-8000-000000000005", 1, -5], ["00000000-0000-4000-8000-000000000006", 1, -6], ["00000000-0000-4000-8000-000000000007", 1, -7], ["00000000-0000-4000-8000-000000000008", 1, -8], ["00000000-0000-4000-8000-000000000009", 1, -9], ["00000000-0000-4000-8000-000000000010", 1, -10], ["00000000-0000-4000-8000-000000000011", 1, -11], ["00000000-0000-4000-8000-000000000012", 1, -12], ["00000000-0000-4000-8000-000000000013", 1, -13], ["00000000-0000-4000-8000-000000000014", 1, -14], ["00000000-0000-4000-8000-000000000015", 1, -15], ["00000000-0000-4000-8000-000000000016", 1, -16], ["00000000-0000-4000-8000-000000000017", 1, -17], ["00000000-0000-4000-8000-000000000018", 1, -18], ["00000000-0000-4000-8000-000000000019", 1, -19], ["00000000-0000-4000-8000-000000000020", 1, -20], ["00000000-0000-4000-8000-000000000021", 1, -21], ["00000000-0000-4000-8000-000000000022", 1, -22], ["00000000-0000-4000-8000-000000000023", 1, -23], ["00000000-0000-4000-8000-000000000024", 1, -24], ["00000000-0000-4000-8000-000000000025", 1, -25], ["00000000-0000-4000-8000-000000000026", 1, -26], ["00000000-0000-4000-8000-000000000027", 1, -27], ["00000000-0000-4000-8000-000000000028", 1, -28], ["00000000-0000-4000-8000-000000000029", 1, -29], ["00000000-0000-4000-8000-000000000030", 1, -30], ["00000000-0000-4000-8000-000000000301", 1, -301], ["00000000-0000-4000-8000-000000000302", 1, -302]]'::jsonb; n int; BEGIN SELECT count(*) INTO n FROM jsonb_array_elements(f) m WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(r->'items') i WHERE i->>'interpretation_id' = m->>0 AND (i->>'version')::int = (m->>1)::int AND i->>'class' = 'MATCH' AND (i->>'assertion_id')::bigint = (m->>2)::bigint); IF n <> jsonb_array_length(f) THEN RAISE EXCEPTION 'MACHINE_NOT_MATCH % af %', jsonb_array_length(f) - n, jsonb_array_length(f); END IF; END $m$;
