RESET ROLE;
-- (5) binding
SELECT set_config('daa.transfer_scope', (SELECT jsonb_agg(interpretation_key::text ORDER BY interpretation_key::text COLLATE "C") FROM private.interpretation WHERE id IN ('00000000-0000-4000-8000-000000000001'::uuid,'00000000-0000-4000-8000-000000000002'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,'00000000-0000-4000-8000-000000000004'::uuid,'00000000-0000-4000-8000-000000000005'::uuid,'00000000-0000-4000-8000-000000000006'::uuid,'00000000-0000-4000-8000-000000000007'::uuid,'00000000-0000-4000-8000-000000000008'::uuid,'00000000-0000-4000-8000-000000000009'::uuid,'00000000-0000-4000-8000-000000000010'::uuid,'00000000-0000-4000-8000-000000000011'::uuid,'00000000-0000-4000-8000-000000000012'::uuid,'00000000-0000-4000-8000-000000000013'::uuid,'00000000-0000-4000-8000-000000000014'::uuid,'00000000-0000-4000-8000-000000000015'::uuid,'00000000-0000-4000-8000-000000000016'::uuid,'00000000-0000-4000-8000-000000000017'::uuid,'00000000-0000-4000-8000-000000000018'::uuid,'00000000-0000-4000-8000-000000000019'::uuid,'00000000-0000-4000-8000-000000000020'::uuid,'00000000-0000-4000-8000-000000000021'::uuid,'00000000-0000-4000-8000-000000000022'::uuid,'00000000-0000-4000-8000-000000000023'::uuid,'00000000-0000-4000-8000-000000000024'::uuid,'00000000-0000-4000-8000-000000000025'::uuid,'00000000-0000-4000-8000-000000000026'::uuid,'00000000-0000-4000-8000-000000000027'::uuid,'00000000-0000-4000-8000-000000000028'::uuid,'00000000-0000-4000-8000-000000000029'::uuid,'00000000-0000-4000-8000-000000000030'::uuid,'00000000-0000-4000-8000-000000000301'::uuid,'00000000-0000-4000-8000-000000000302'::uuid))::text, true) \g /dev/null
\o /dev/null
\i .claude/skills/daa-extract/scripts/interpretation_promotion_targets_scoped.sql
\o
DO $n$ DECLARE t jsonb := current_setting('daa.targets_scoped')::jsonb; faktisk jsonb; forventet jsonb := '["00000000-0000-4000-8000-000000000001", "00000000-0000-4000-8000-000000000002", "00000000-0000-4000-8000-000000000003", "00000000-0000-4000-8000-000000000004", "00000000-0000-4000-8000-000000000005", "00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-000000000007", "00000000-0000-4000-8000-000000000008", "00000000-0000-4000-8000-000000000009", "00000000-0000-4000-8000-000000000010", "00000000-0000-4000-8000-000000000011", "00000000-0000-4000-8000-000000000012", "00000000-0000-4000-8000-000000000013", "00000000-0000-4000-8000-000000000014", "00000000-0000-4000-8000-000000000015", "00000000-0000-4000-8000-000000000016", "00000000-0000-4000-8000-000000000017", "00000000-0000-4000-8000-000000000018", "00000000-0000-4000-8000-000000000019", "00000000-0000-4000-8000-000000000020", "00000000-0000-4000-8000-000000000021", "00000000-0000-4000-8000-000000000022", "00000000-0000-4000-8000-000000000023", "00000000-0000-4000-8000-000000000024", "00000000-0000-4000-8000-000000000025", "00000000-0000-4000-8000-000000000026", "00000000-0000-4000-8000-000000000027", "00000000-0000-4000-8000-000000000028", "00000000-0000-4000-8000-000000000029", "00000000-0000-4000-8000-000000000030", "00000000-0000-4000-8000-000000000301", "00000000-0000-4000-8000-000000000302"]'::jsonb; r jsonb := '[]'::jsonb; n int; BEGIN SELECT coalesce(jsonb_agg(ni.supersedes_id::text ORDER BY ni.supersedes_id), '[]') INTO faktisk FROM jsonb_array_elements(t->'items') x JOIN private.interpretation ni ON ni.id = (x->>'interpretation_id')::uuid; IF faktisk IS DISTINCT FROM forventet OR jsonb_array_length(t->'singleton_items') <> 0 THEN RAISE EXCEPTION 'CONTROL_V2_TARGETS_MISMATCH faktisk=% forventet=%', jsonb_array_length(faktisk), jsonb_array_length(forventet); END IF; SELECT count(*) INTO n FROM jsonb_array_elements(t->'items') x JOIN private.interpretation ni ON ni.id = (x->>'interpretation_id')::uuid JOIN jsonb_array_elements(r) m ON m->>0 = ni.supersedes_id::text WHERE x->>'target_type' = 'assertion' AND (x->>'target_id')::bigint = (m->>1)::bigint; IF n <> jsonb_array_length(r) THEN RAISE EXCEPTION 'CONTROL_V2_RETTELSE_MAAL_MISMATCH % af %', n, jsonb_array_length(r); END IF; END $n$;
SET LOCAL ROLE authenticated;
DO $b$ DECLARE items jsonb := current_setting('daa.targets_scoped')::jsonb->'items'; p jsonb; BEGIN PERFORM set_config('app.change_set_id','',true); p := public.red_preview_interpretation_promotions(items); IF jsonb_array_length(p->'items') <> jsonb_array_length(items) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'items') i WHERE (i->>'eligible')::boolean IS NOT TRUE) THEN RAISE EXCEPTION 'CONTROL_V2_BIND_NOT_ELIGIBLE'; END IF; PERFORM set_config('app.change_set_id','',true); PERFORM public.red_promote_interpretations_batch(items, p->>'preview_hash'); END $b$;
RESET ROLE;
DO $a$ BEGIN IF EXISTS (SELECT 1 FROM pg_class c WHERE c.oid IN ('private.interpretation'::regclass, 'private.interpretation_promotion'::regclass) AND NOT pg_has_role(current_user, c.relowner, 'USAGE')) THEN RAISE EXCEPTION 'CONTROL_V2_ANALYZE_IKKE_EJER'; END IF; END $a$; ANALYZE private.interpretation; ANALYZE private.interpretation_promotion;
DO $c$ DECLARE n int; BEGIN SELECT count(DISTINCT q.interpretation_key) INTO n FROM private.interpretation_promotion pr JOIN private.interpretation q ON q.id = pr.interpretation_id WHERE q.supersedes_id IN ('00000000-0000-4000-8000-000000000001'::uuid,'00000000-0000-4000-8000-000000000002'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,'00000000-0000-4000-8000-000000000004'::uuid,'00000000-0000-4000-8000-000000000005'::uuid,'00000000-0000-4000-8000-000000000006'::uuid,'00000000-0000-4000-8000-000000000007'::uuid,'00000000-0000-4000-8000-000000000008'::uuid,'00000000-0000-4000-8000-000000000009'::uuid,'00000000-0000-4000-8000-000000000010'::uuid,'00000000-0000-4000-8000-000000000011'::uuid,'00000000-0000-4000-8000-000000000012'::uuid,'00000000-0000-4000-8000-000000000013'::uuid,'00000000-0000-4000-8000-000000000014'::uuid,'00000000-0000-4000-8000-000000000015'::uuid,'00000000-0000-4000-8000-000000000016'::uuid,'00000000-0000-4000-8000-000000000017'::uuid,'00000000-0000-4000-8000-000000000018'::uuid,'00000000-0000-4000-8000-000000000019'::uuid,'00000000-0000-4000-8000-000000000020'::uuid,'00000000-0000-4000-8000-000000000021'::uuid,'00000000-0000-4000-8000-000000000022'::uuid,'00000000-0000-4000-8000-000000000023'::uuid,'00000000-0000-4000-8000-000000000024'::uuid,'00000000-0000-4000-8000-000000000025'::uuid,'00000000-0000-4000-8000-000000000026'::uuid,'00000000-0000-4000-8000-000000000027'::uuid,'00000000-0000-4000-8000-000000000028'::uuid,'00000000-0000-4000-8000-000000000029'::uuid,'00000000-0000-4000-8000-000000000030'::uuid,'00000000-0000-4000-8000-000000000301'::uuid,'00000000-0000-4000-8000-000000000302'::uuid) AND private.assertion_binding_current(pr.id); IF n <> 32 THEN RAISE EXCEPTION 'CONTROL_V2_BIND_COUNT % af 32', n; END IF; END $c$;
-- (6) verifikation før COMMIT
DO $v$
DECLARE univ jsonb := '["00000000-0000-4000-8000-000000000001", "00000000-0000-4000-8000-000000000002", "00000000-0000-4000-8000-000000000003", "00000000-0000-4000-8000-000000000004", "00000000-0000-4000-8000-000000000005", "00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-000000000007", "00000000-0000-4000-8000-000000000008", "00000000-0000-4000-8000-000000000009", "00000000-0000-4000-8000-000000000010", "00000000-0000-4000-8000-000000000011", "00000000-0000-4000-8000-000000000012", "00000000-0000-4000-8000-000000000013", "00000000-0000-4000-8000-000000000014", "00000000-0000-4000-8000-000000000015", "00000000-0000-4000-8000-000000000016", "00000000-0000-4000-8000-000000000017", "00000000-0000-4000-8000-000000000018", "00000000-0000-4000-8000-000000000019", "00000000-0000-4000-8000-000000000020", "00000000-0000-4000-8000-000000000021", "00000000-0000-4000-8000-000000000022", "00000000-0000-4000-8000-000000000023", "00000000-0000-4000-8000-000000000024", "00000000-0000-4000-8000-000000000025", "00000000-0000-4000-8000-000000000026", "00000000-0000-4000-8000-000000000027", "00000000-0000-4000-8000-000000000028", "00000000-0000-4000-8000-000000000029", "00000000-0000-4000-8000-000000000030", "00000000-0000-4000-8000-000000000101", "00000000-0000-4000-8000-000000000102", "00000000-0000-4000-8000-000000000103", "00000000-0000-4000-8000-000000000201", "00000000-0000-4000-8000-000000000202", "00000000-0000-4000-8000-000000000301", "00000000-0000-4000-8000-000000000302"]'::jsonb;
        forventet jsonb := '["00000000-0000-4000-8000-000000000001", "00000000-0000-4000-8000-000000000002", "00000000-0000-4000-8000-000000000003", "00000000-0000-4000-8000-000000000004", "00000000-0000-4000-8000-000000000005", "00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-000000000007", "00000000-0000-4000-8000-000000000008", "00000000-0000-4000-8000-000000000009", "00000000-0000-4000-8000-000000000010", "00000000-0000-4000-8000-000000000011", "00000000-0000-4000-8000-000000000012", "00000000-0000-4000-8000-000000000013", "00000000-0000-4000-8000-000000000014", "00000000-0000-4000-8000-000000000015", "00000000-0000-4000-8000-000000000016", "00000000-0000-4000-8000-000000000017", "00000000-0000-4000-8000-000000000018", "00000000-0000-4000-8000-000000000019", "00000000-0000-4000-8000-000000000020", "00000000-0000-4000-8000-000000000021", "00000000-0000-4000-8000-000000000022", "00000000-0000-4000-8000-000000000023", "00000000-0000-4000-8000-000000000024", "00000000-0000-4000-8000-000000000025", "00000000-0000-4000-8000-000000000026", "00000000-0000-4000-8000-000000000027", "00000000-0000-4000-8000-000000000028", "00000000-0000-4000-8000-000000000029", "00000000-0000-4000-8000-000000000030", "00000000-0000-4000-8000-000000000301", "00000000-0000-4000-8000-000000000302"]'::jsonb;
        pp jsonb := '[]'::jsonb;
        faktisk jsonb; n int;
BEGIN
  SELECT coalesce(jsonb_agg(u.id ORDER BY u.id::uuid), '[]') INTO faktisk
    FROM (SELECT x AS id FROM jsonb_array_elements_text(univ) x) u
    JOIN private.interpretation i ON i.id = u.id::uuid
   WHERE EXISTS (SELECT 1 FROM private.interpretation_promotion pr
                   JOIN private.interpretation q ON q.id = pr.interpretation_id
                  WHERE q.interpretation_key = i.interpretation_key
                    AND private.assertion_binding_current(pr.id));
  IF faktisk IS DISTINCT FROM forventet THEN
    RAISE EXCEPTION 'CONTROL_V2_PROMOTION_MISMATCH faktisk=% forventet=%',
      jsonb_array_length(faktisk), jsonb_array_length(forventet);
  END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements_text(pp) p
   WHERE NOT EXISTS (SELECT 1 FROM private.source_persona_identity spi
                      WHERE spi.source_persona_id = p::uuid AND spi.decision_status = 'unresolved');
  IF n <> 0 THEN RAISE EXCEPTION 'CONTROL_V2_P_PERSONA_IDENTITY %', n; END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements_text(univ) u
    JOIN private.interpretation i ON i.id = u::uuid
    JOIN private.interpretation_current ic ON ic.interpretation_key = i.interpretation_key
   WHERE ic.source_persona_id::text IN (SELECT jsonb_array_elements_text(pp))
     AND (ic.status <> 'proposed' OR EXISTS (SELECT 1 FROM private.interpretation_promotion pr
            JOIN private.interpretation q ON q.id = pr.interpretation_id
           WHERE q.interpretation_key = i.interpretation_key));
  IF n <> 0 THEN RAISE EXCEPTION 'CONTROL_V2_P_PERSONA_DECIDED %', n; END IF;
  RAISE NOTICE 'CONTROL_V2_VERIFY_OK bundet=% p_personas=%', jsonb_array_length(faktisk),
    jsonb_array_length(pp);
END $v$;
COMMIT;
\echo 'CONTROL_V2_OK unresolved=0 rettelser=0 afgoerelser=5 stikproeve=20 maskine=12 bundet=32'
